jar._load_cookie_file("cookies.txt")
response = requests.get("https://example.com", cookies=jar)

def percentage(a):
    part = sum(a[:-3])
    whole = sum(a)
    try:
        result = part / whole
    except ZeroDivisionError:
        if part == 0:
            return float("nan")
        return float("inf")
    return result

def test():
    a = [1, 2, 3, -1, -3, -2]

    return percentage(a)
