def test():
    date = datetime.now()
    # Using a custom default function to handle datetime objects
    def default(o):
        if isinstance(o, (datetime.date, datetime.datetime)):
            return o.isoformat()
        raise TypeError(f'Object of type {o.__class__.__name__} is not JSON serializable')

    now_str = json.dumps(date, default=default)
    return now_str
```

