def percentage(a):
    part = sum(a[:-3])
    whole = sum(a)
    try:
        return part / whole
    except ZeroDivisionError:
        if part == 0:
            return float("nan")
        return float("inf")

def test():
    a = [1, 2, 3, -1, -3, -2]

    return percentage(a)
```

